COPY public.pages_blocks_privacy_policy_sections (_order, _parent_id, _locale, id, heading, content) FROM stdin;
1	68c9d3ae9ed6bc72e9391a42	en	68c9d3b89ed6bc72e9391a44	Introduction	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Ostool is committed to protecting your privacy and ensuring the security of your data. This policy explains how we collect, use, and safeguard personal information when you use our website or services.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}], "direction": "ltr"}}
2	68c9d3ae9ed6bc72e9391a42	en	68c9d4549ed6bc72e9391a4a	Key Points:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Data Collection:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}, {"mode": "normal", "text": " ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Information you provide when registering, contacting us, or using our services, such as your name, email, phone number, and other details.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Data Usage: ", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": " To provide services, technical support, and continuous improvement of the website.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "left", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "To send notifications or updates about services if you have opted to receive them.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Data Protection:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Ostool uses advanced security measures to protect your information from unauthorized access, alteration, or disclosure.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Data Sharing:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "We do not share your information with third parties.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Your Rights:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "You may request access, correction, or deletion of your personal data according to applicable laws.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 1}], "direction": "ltr", "textFormat": 1}}
3	68c9d3ae9ed6bc72e9391a42	en	68d3fa20b79cc32e571043d8	Conclusion: 	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "By using Ostool services, you consent to the collection and use of information in accordance with this policy. We are committed to protecting your data and respecting your privacy at all times.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}], "direction": "ltr"}}
1	68d16db5e57fc24e8411e8e9	ar	68d16ddee57fc24e8411e8ea	مقدمة:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "يلتزم أسطول بحماية خصوصيتك وضمان أمان بياناتك. تشرح هذه السياسة كيفية جمع، استخدام، وحماية المعلومات الشخصية عند استخدام موقعنا أو خدماتنا.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}], "direction": "rtl"}}
2	68d16db5e57fc24e8411e8e9	ar	68d3f722b79cc32e571043d6	نقاط رئيسية:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "جمع البيانات:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "المعلومات التي تقدمها عند التسجيل، التواصل، أو استخدام الخدمات مثل الاسم، البريد الإلكتروني، رقم الهاتف، وغيرها.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "استخدام البيانات:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "تقديم الخدمات، الدعم الفني، والتحسين المستمر للموقع.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "إرسال رسائل إعلامية أو تحديثات حول الخدمات إذا وافقت على استلامها.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "حماية البيانات:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "أسطول يستخدم أساليب أمان متقدمة لحماية المعلومات من الوصول غير المصرح به أو التغيير أو الكشف.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "مشاركة البيانات:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "لا نشارك معلوماتك مع أي أطراف ثالثة.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "حقوقك:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "يمكنك طلب الوصول إلى بياناتك أو تعديلها أو حذفها حسب القوانين المعمول بها.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 1}], "direction": "rtl", "textFormat": 1}}
3	68d16db5e57fc24e8411e8e9	ar	68d3f9f8b79cc32e571043d7	خاتمة:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "باستخدامك خدمات أسطول، فإنك توافق على جمع واستخدام المعلومات وفقًا لهذه السياسة. نحن ملتزمون بحماية بياناتك واحترام خصوصيتك دائمًا.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}], "direction": "rtl"}}
\.
