COPY public.pages_blocks_terms_and_conditions (_order, _parent_id, _path, _locale, id, main_title, introduction, block_name) FROM stdin;
1	8	layout	en	68c9d8ea1df3ee7929530474	Terms & Conditions – Ostool	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Welcome to Ostool. By using our website and services, you agree to comply with the following terms and conditions. Please read these terms carefully before using the site or any Ostool service.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"mode": "normal", "text": " ", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}], "direction": "ltr"}}	\N
1	8	layout	ar	68d16d69e57fc24e8411e8e7	الشروط والأحكام – أسطول	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "مرحبًا بكم في أسطول. باستخدامكم لموقعنا وخدماتنا، فإنكم توافقون على الالتزام بالشروط والأحكام التالية. يرجى قراءة هذه الشروط بعناية قبل استخدام الموقع أو أي خدمة مقدمة من أسطول.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}, {"type": "linebreak", "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}], "direction": "rtl"}}	\N
