COPY public.pages_blocks_terms_and_conditions_sections (_order, _parent_id, _locale, id, heading, content) FROM stdin;
1	68c9d8ea1df3ee7929530474	en	68d3fd54b79cc32e571043dc	Main Terms:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Use of Service:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "Using the site for any unlawful or prohibited purpose is strictly forbidden.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Intellectual Property:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "All content, logos, images, and software on Ostool are owned by or licensed to the company.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "Copying or redistributing any content without explicit permission from Ostool is prohibited.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "User Account:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "All information provided must be accurate and up-to-date.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "Users are responsible for maintaining the confidentiality of their login credentials.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Limitation of Liability:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "Ostool is not responsible for any damages arising from the use of the website or related services, except as required by law.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Changes to Terms:", "type": "text", "style": "", "detail": 0, "format": 1, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 1}, {"type": "paragraph", "format": "", "indent": 1, "version": 1, "children": [{"mode": "normal", "text": "Ostool may modify these terms at any time, and the updates become effective upon posting on the website.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}], "direction": "ltr", "textFormat": 1}}
2	68c9d8ea1df3ee7929530474	en	68d3fa86b79cc32e571043d9	Conclusion:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "By using our site, you agree to be bound by these terms and conditions. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "ltr", "textStyle": "", "textFormat": 0}], "direction": "ltr"}}
1	68d16d69e57fc24e8411e8e7	ar	68d3fcf0b79cc32e571043db	الشروط الرئيسية:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "start", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "استخدام الخدمة: يحظر استخدام الموقع لأي غرض غير قانوني أو مخالف لهذه الشروط.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "start", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "الملكية الفكرية: جميع المحتويات، الشعارات، الصور، والبرمجيات على أسطول مملوكة للشركة أو مرخصة لها. لا يجوز نسخ أو إعادة توزيع أي محتوى دون إذن صريح من أسطول.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "start", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "حساب المستخدم: يجب أن تكون جميع البيانات المقدمة دقيقة وحديثة. المستخدم مسؤول عن سرية بيانات تسجيل الدخول الخاصة به.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "start", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "حدود المسؤولية: أسطول لا يتحمل أي أضرار ناتجة عن استخدام الموقع أو أي خدمات مرتبطة، ما لم ينص القانون على خلاف ذلك. يمكن لأسطول تعديل هذه الشروط في أي وقت، وستكون التحديثات سارية بمجرد نشرها على الموقع.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}], "direction": "rtl"}}
2	68d16d69e57fc24e8411e8e7	ar	68d16d84e57fc24e8411e8e8	خاتمة:	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "باستخدامك موقعنا، فإنك توافق على الالتزام بالشروط والأحكام كاملة.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": "rtl", "textStyle": "", "textFormat": 0}], "direction": "rtl"}}
\.
